DATA_IMPORT_RESET_OPERATIONS = {
    ("POST", "/api/import"): "import",
    ("POST", "/api/reset"): "reset",
    ("PUT", "/api/state"): "state_replace",
}


def current_data_import_reset_operation() -> str | None:
    return DATA_IMPORT_RESET_OPERATIONS.get((request.method, request.path))


def data_import_reset_denial_reason(user: dict | None) -> str | None:
    if not user:
        return "unauthenticated"
    if user.get("role") != "admin":
        return "not_admin"
    if ENVIRONMENT.environment not in {"development", "staging"}:
        return "capability_disabled"
    if not ENVIRONMENT.allow_data_import_reset:
        return "capability_disabled"
    return None


def data_import_reset_capabilities(user: dict | None) -> dict:
    return {"dataImportReset": data_import_reset_denial_reason(user) is None}


def log_blocked_data_operation(operation: str, reason: str) -> None:
    app.logger.warning(
        "Operacao destrutiva bloqueada. operation=%s reason=%s",
        operation,
        reason,
    )


class AuthenticationDatabaseUnavailable(RuntimeError):
    pass


def database_unavailable_response():
    return jsonify({"ok": False, "error": AUTH_DATABASE_UNAVAILABLE_MESSAGE}), 503


@app.after_request
def no_cache(response):
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    if IS_PRODUCTION:
        response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    return response


@app.before_request
def require_login_for_api():
    if not request.path.startswith("/api/"):
        return None
    if request.path in {
        "/api/health",
        "/api/readiness",
        "/api/session",
        "/api/login",
        "/api/logout",
        "/api/store/operational-settings",
    }:
        return None
    if not session.get("user"):
        operation = current_data_import_reset_operation()
        if operation:
            log_blocked_data_operation(operation, "unauthenticated")
        return jsonify({"ok": False, "error": "Login obrigatório."}), 401
    return None


@app.before_request
def protect_data_import_reset_before_database_access():
    operation = current_data_import_reset_operation()
    if not operation:
        return None
    reason = data_import_reset_denial_reason(session.get("user"))
    if reason == "not_admin":
        log_blocked_data_operation(operation, reason)
        return jsonify({"ok": False, "error": "Apenas administrador pode realizar esta ação."}), 403
    if reason == "capability_disabled":
        log_blocked_data_operation(operation, reason)
        return jsonify({"ok": False, "error": "Operação indisponível neste ambiente."}), 403
    return None


@app.before_request
def validate_active_session_for_api():
    if not request.path.startswith("/api/"):
        return None
    if request.path in {
        "/api/health",
        "/api/readiness",
        "/api/session",
        "/api/login",
        "/api/logout",
        "/api/store/operational-settings",
    }:
        return None
    if not session.get("user"):
        return None
    try:
        refreshed_user = refresh_session_user()
    except AuthenticationDatabaseUnavailable:
        return database_unavailable_response()
    if not refreshed_user:
        operation = current_data_import_reset_operation()
        if operation:
            log_blocked_data_operation(operation, "invalid_session")
        session.clear()
        return jsonify({"ok": False, "error": "Sessao expirada. Faca login novamente."}), 401
    return None


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def refresh_session_user() -> dict | None:
    user = session.get("user")
    if not user:
        return None
    row = fetch_auth_user_by_id(user.get("id"))
    if not row or not row["active"]:
        return None
    public = public_user(row)
    if public != user:
        session["user"] = public
    return public


def client_rate_key(login: str) -> str:
    forwarded_for = request.headers.get("X-Forwarded-For", "")
    ip = forwarded_for.split(",", 1)[0].strip() or request.remote_addr or "unknown"
    return f"{ip}:{login.casefold()}"


def login_blocked(login: str) -> bool:
    key = client_rate_key(login)
    cutoff = datetime.now(timezone.utc) - timedelta(seconds=LOGIN_ATTEMPT_WINDOW_SECONDS)
    LOGIN_ATTEMPTS[key] = [item for item in LOGIN_ATTEMPTS.get(key, []) if item > cutoff]
    return len(LOGIN_ATTEMPTS[key]) >= LOGIN_ATTEMPT_LIMIT


def register_login_failure(login: str) -> None:
    key = client_rate_key(login)
    cutoff = datetime.now(timezone.utc) - timedelta(seconds=LOGIN_ATTEMPT_WINDOW_SECONDS)
    attempts = [item for item in LOGIN_ATTEMPTS.get(key, []) if item > cutoff]
    attempts.append(datetime.now(timezone.utc))
    LOGIN_ATTEMPTS[key] = attempts


def clear_login_failures(login: str) -> None:
    LOGIN_ATTEMPTS.pop(client_rate_key(login), None)


def validate_password_strength(password: str) -> str | None:
    if not IS_PRODUCTION or not password:
        return None
    if len(password) < 8:
        return "Em produção, a senha deve ter pelo menos 8 caracteres."
    if password.lower() in {"1234", "admin", "senha", "password"}:
        return "Escolha uma senha mais forte."
    if password.isdigit() or password.isalpha():
        return "Use uma senha com letras, números ou símbolos."
    return None


class DbRow(dict):
    def __init__(self, keys, values):
        super().__init__(zip(keys, values))
        self._values = list(values)

    def __getitem__(self, key):
        if isinstance(key, int):
            return self._values[key]
        return super().__getitem__(key)


class EmptyCursor:
    def fetchone(self):
        return None

    def fetchall(self):
        return []


class PgCursor:
    def __init__(self, cursor):
        self.cursor = cursor
        self.keys = [getattr(item, "name", item[0]) for item in cursor.description] if cursor.description else []

    def _row(self, values):
        if values is None:
            return None
        return DbRow(self.keys, values)

    def fetchone(self):
        return self._row(self.cursor.fetchone())

    def fetchall(self):
        return [self._row(row) for row in self.cursor.fetchall()]


class PgConnection:
    def __init__(self, url: str):
        import psycopg2

        self.conn = psycopg2.connect(url)

    def execute(self, sql: str, params=()):
        translated = translate_postgres_sql(sql)
        if translated is None:
            return EmptyCursor()
        cursor = self.conn.cursor()
        cursor.execute(translated, params or ())
        return PgCursor(cursor)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        if exc_type:
            self.conn.rollback()
        else:
            self.conn.commit()
        self.conn.close()


def translate_postgres_sql(sql: str) -> str | None:
    stripped = sql.strip()
    upper = stripped.upper()
    if upper.startswith("PRAGMA"):
        return None
    if upper.startswith("INSERT OR IGNORE INTO STORES"):
        sql = "INSERT INTO stores (id, name, created_at) VALUES (?, ?, ?) ON CONFLICT (id) DO NOTHING"
    sql = sql.replace("ORDER BY name COLLATE NOCASE", "ORDER BY LOWER(name)")
    for alias in POSTGRES_CAMEL_ALIASES:
        sql = sql.replace(f" AS {alias}", f' AS "{alias}"')
    return sql.replace("?", "%s")


def connect_db():
    if USE_POSTGRES:
        return PgConnection(DATABASE_URL)
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute(f"PRAGMA busy_timeout = {DB_BUSY_TIMEOUT_MS}")
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute("PRAGMA synchronous = NORMAL")
    return conn


def _is_auth_database_error(error: Exception) -> bool:
    if isinstance(error, (sqlite3.Error, ImportError)):
        return True
    if not USE_POSTGRES:
        return False
    try:
        import psycopg2
    except ImportError:
        return False
    return isinstance(error, psycopg2.Error)


def _open_auth_read_connection():
    if USE_POSTGRES:
        connection = PgConnection(DATABASE_URL)
        connection.conn.set_session(readonly=True, autocommit=False)
        return connection
    database_uri = f"{Path(DB_PATH).resolve().as_uri()}?mode=ro"
    connection = sqlite3.connect(
        database_uri,
        uri=True,
        timeout=DB_BUSY_TIMEOUT_MS / 1000,
    )
    connection.row_factory = sqlite3.Row
    return connection


def _close_auth_read_connection(connection) -> None:
    if USE_POSTGRES:
        try:
            connection.conn.rollback()
        finally:
            connection.conn.close()
        return
    connection.close()


def _query_auth_user(sql: str, params: tuple):
    connection = None
    try:
        connection = _open_auth_read_connection()
        row = connection.execute(sql, params).fetchone()
        _close_auth_read_connection(connection)
        connection = None
        return row
    except Exception as error:
        if connection is not None:
            try:
                _close_auth_read_connection(connection)
            except Exception:
                pass
        if _is_auth_database_error(error):
            app.logger.error("Falha operacional ao consultar autenticacao no banco de dados.")
            raise AuthenticationDatabaseUnavailable() from error
        raise


def fetch_auth_user_by_id(user_id: str | None):
    return _query_auth_user(
        """
        SELECT id, name, login, role, active, failed_login_attempts, blocked_at, last_login_at
        FROM users
        WHERE store_id = ? AND id = ?
        """,
        ("matriz", user_id),
    )


def fetch_auth_user_by_login(login: str):
    return _query_auth_user(
        """
        SELECT id, name, login, password_hash, role, active,
               failed_login_attempts, blocked_at, last_login_at
        FROM users
        WHERE store_id = ? AND login = ?
        """,
        ("matriz", login),
    )


def _readiness_result(ready: bool, state: str, detail: str = "") -> dict:
    return {"ready": ready, "state": state, "detail": detail}


def _is_readiness_database_error(error: Exception) -> bool:
    if isinstance(error, (sqlite3.Error, ImportError)):
        return True
    if not USE_POSTGRES:
        return False
    try:
        import psycopg2
    except ImportError:
        return False
    return isinstance(error, psycopg2.Error)


def _open_readiness_connection():
    if USE_POSTGRES:
        connection = PgConnection(DATABASE_URL)
        connection.conn.set_session(readonly=True, autocommit=False)
        return connection
    database_uri = f"{Path(DB_PATH).resolve().as_uri()}?mode=ro"
    connection = sqlite3.connect(
        database_uri,
        uri=True,
        timeout=DB_BUSY_TIMEOUT_MS / 1000,
    )
    connection.row_factory = sqlite3.Row
    return connection


def _close_readiness_connection(connection) -> None:
    if USE_POSTGRES:
        try:
            connection.conn.rollback()
        finally:
            connection.conn.close()
        return
    connection.close()


def _normalize_postgresql_index(index_definition: str) -> tuple[bool, tuple[str, ...]]:
    definition = str(index_definition or "")
    start = definition.find("(")
    end = definition.find(")", start + 1)
    if start < 0 or end < 0:
        return False, ()
    columns = tuple(
        part.strip().strip('"').split()[0].strip('"').lower()
        for part in definition[start + 1:end].split(",")
        if part.strip()
    )
    return "CREATE UNIQUE INDEX" in definition.upper(), columns


def inspect_sqlite_schema(connection) -> dict:
    table_rows = connection.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table'"
    ).fetchall()
    tables = {str(row["name"]) for row in table_rows}
    columns = {}
    for table_name in REQUIRED_SCHEMA_TABLES | {"schema_migrations"}:
        if table_name not in tables:
            continue
        rows = connection.execute(f'PRAGMA table_info("{table_name}")').fetchall()
        columns[table_name] = {str(row["name"]) for row in rows}

    indexes = {}
    for table_name, _, _ in REQUIRED_SCHEMA_INDEXES.values():
        if table_name not in tables:
            continue
        for row in connection.execute(f'PRAGMA index_list("{table_name}")').fetchall():
            index_name = str(row["name"])
            index_columns = connection.execute(
                f'PRAGMA index_info("{index_name}")'
            ).fetchall()
            indexes[index_name] = {
                "table": table_name,
                "columns": tuple(str(item["name"]) for item in index_columns),
                "unique": bool(row["unique"]),
            }

    versions = None
    version_column_present = False
    if "schema_migrations" in tables:
        version_column_present = "version" in columns.get("schema_migrations", set())
        if version_column_present:
            versions = [
                row["version"]
                for row in connection.execute("SELECT version FROM schema_migrations").fetchall()
            ]
    return {
        "tables": tables,
        "columns": columns,
        "indexes": indexes,
        "versions": versions,
        "version_column_present": version_column_present,
    }


def inspect_postgresql_schema(connection) -> dict:
    table_rows = connection.execute(
        """
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = 'public'
        """
    ).fetchall()
    tables = {str(row["table_name"]) for row in table_rows}
    column_rows = connection.execute(
        """
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
        """
    ).fetchall()
    columns = {}
    for row in column_rows:
        columns.setdefault(str(row["table_name"]), set()).add(str(row["column_name"]))

    index_rows = connection.execute(
        """
        SELECT tablename, indexname, indexdef
        FROM pg_indexes
        WHERE schemaname = 'public'
        """
    ).fetchall()
    indexes = {}
    for row in index_rows:
        unique, index_columns = _normalize_postgresql_index(row["indexdef"])
        indexes[str(row["indexname"])] = {
            "table": str(row["tablename"]),
            "columns": index_columns,
            "unique": unique,
        }

    versions = None
    version_column_present = False
    if "schema_migrations" in tables:
        version_column_present = "version" in columns.get("schema_migrations", set())
        if version_column_present:
            versions = [
                row["version"]
                for row in connection.execute("SELECT version FROM schema_migrations").fetchall()
            ]
    return {
        "tables": tables,
        "columns": columns,
        "indexes": indexes,
        "versions": versions,
        "version_column_present": version_column_present,
    }


def validate_readiness_schema(metadata: dict) -> dict:
    tables = metadata.get("tables", set())
    missing_tables = REQUIRED_SCHEMA_TABLES - tables
    if missing_tables:
        return _readiness_result(False, READINESS_SCHEMA_MISSING, "required_table_missing")

    columns = metadata.get("columns", {})
    for table_name, required_columns in REQUIRED_SCHEMA_COLUMNS.items():
        if required_columns - columns.get(table_name, set()):
            return _readiness_result(False, READINESS_SCHEMA_INCOMPLETE, "required_column_missing")

    indexes = metadata.get("indexes", {})
    for index_name, (table_name, index_columns, unique) in REQUIRED_SCHEMA_INDEXES.items():
        actual = indexes.get(index_name)
        if not actual:
            return _readiness_result(False, READINESS_SCHEMA_INCOMPLETE, "required_index_missing")
        if (
            actual.get("table") != table_name
            or tuple(actual.get("columns", ())) != index_columns
            or bool(actual.get("unique")) != unique
        ):
            return _readiness_result(False, READINESS_SCHEMA_INCOMPLETE, "required_index_invalid")

    if "schema_migrations" not in tables:
        return _readiness_result(True, READINESS_READY_LEGACY, "legacy_schema_without_version")
    if not metadata.get("version_column_present"):
        return _readiness_result(False, READINESS_SCHEMA_INVALID, "version_column_missing")
    versions = metadata.get("versions")
    if not versions or any(
        isinstance(version, bool) or not isinstance(version, int) or version <= 0
        for version in versions
    ):
        return _readiness_result(False, READINESS_SCHEMA_INVALID, "invalid_schema_version")
    current_version = max(versions)
    if current_version < REQUIRED_SCHEMA_VERSION:
        return _readiness_result(False, READINESS_SCHEMA_OUTDATED, "schema_version_outdated")
    if current_version > REQUIRED_SCHEMA_VERSION:
        return _readiness_result(False, READINESS_SCHEMA_FUTURE, "schema_version_future")
    return _readiness_result(True, READINESS_READY_VERSIONED, "schema_version_supported")


def check_database_readiness() -> dict:
    connection = None
    result = None
    try:
        connection = _open_readiness_connection()
        metadata = (
            inspect_postgresql_schema(connection)
            if USE_POSTGRES
            else inspect_sqlite_schema(connection)
        )
        result = validate_readiness_schema(metadata)
    except Exception as error:
        state = (
            READINESS_DATABASE_UNAVAILABLE
            if _is_readiness_database_error(error)
            else READINESS_SCHEMA_INVALID
        )
        result = _readiness_result(False, state, "readiness_inspection_failed")
    finally:
        if connection is not None:
            try:
                _close_readiness_connection(connection)
            except Exception:
                result = _readiness_result(False, READINESS_DATABASE_UNAVAILABLE, "readiness_close_failed")
    return result or _readiness_result(False, READINESS_SCHEMA_INVALID, "readiness_result_missing")


def ensure_backup_dir() -> None:
    os.makedirs(BACKUP_DIR, exist_ok=True)


def create_database_backup(reason: str = "manual") -> dict:
    if USE_POSTGRES:
        raise RuntimeError("Backup manual por arquivo nao se aplica ao PostgreSQL. Use backup/snapshot da hospedagem.")
    ensure_backup_dir()
    init_db()
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    safe_reason = "".join(char for char in reason.lower().strip().replace(" ", "-") if char.isalnum() or char in {"-", "_"}) or "manual"
    filename = f"loja-{stamp}-{safe_reason}.db"
    path = os.path.join(BACKUP_DIR, filename)
    with connect_db() as source, sqlite3.connect(path) as target:
        source.execute("PRAGMA wal_checkpoint(FULL)")
        source.backup(target)
    return {
        "filename": filename,
        "path": path,
        "size": os.path.getsize(path),
        "createdAt": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
    }


def list_database_backups() -> list[dict]:
    if USE_POSTGRES:
        return []
    ensure_backup_dir()
    backups = []
    for entry in os.scandir(BACKUP_DIR):
        if not entry.is_file() or not entry.name.endswith(".db"):
            continue
        stat = entry.stat()
        backups.append({
            "filename": entry.name,
            "size": stat.st_size,
            "createdAt": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
        })
    return sorted(backups, key=lambda item: item["createdAt"], reverse=True)


def prune_database_backups(keep: int = 30) -> None:
    backups = list_database_backups()
    for backup in backups[keep:]:
        try:
            os.remove(os.path.join(BACKUP_DIR, backup["filename"]))
        except FileNotFoundError:
            pass


def database_file_size(path: str) -> int:
    return os.path.getsize(path) if os.path.exists(path) else 0


def database_status() -> dict:
    init_db()
    backup_items = list_database_backups()
    table_names = [
        "products",
        "customers",
        "sales",
        "cash_movements",
        "receivables",
        "payables",
        "cash_closings",
        "users",
        "audit_logs",
    ]
    counts = {}
    if USE_POSTGRES:
        with connect_db() as conn:
            version = conn.execute("SELECT version() AS version").fetchone()["version"]
            database_name = conn.execute("SELECT current_database() AS name").fetchone()["name"]
            size = int(conn.execute("SELECT pg_database_size(current_database()) AS size").fetchone()["size"])
            for table in table_names:
                try:
                    counts[table] = int(conn.execute(f"SELECT COUNT(*) AS total FROM {table}").fetchone()["total"])
                except Exception:
                    counts[table] = 0
        return {
            "engine": "PostgreSQL",
            "path": database_name,
            "filename": database_name,
            "size": size,
            "walSize": 0,
            "shmSize": 0,
            "journalMode": "server-managed",
            "synchronous": "server-managed",
            "foreignKeys": True,
            "busyTimeoutMs": None,
            "pageCount": None,
            "pageSize": None,
            "estimatedDataSize": size,
            "integrity": "ok",
            "foreignKeyErrors": 0,
            "counts": counts,
            "backupCount": len(backup_items),
            "lastBackup": backup_items[0] if backup_items else None,
            "version": version,
        }
    with connect_db() as conn:
        journal_mode = conn.execute("PRAGMA journal_mode").fetchone()[0]
        synchronous = conn.execute("PRAGMA synchronous").fetchone()[0]
        foreign_keys = bool(conn.execute("PRAGMA foreign_keys").fetchone()[0])
        page_count = int(conn.execute("PRAGMA page_count").fetchone()[0])
        page_size = int(conn.execute("PRAGMA page_size").fetchone()[0])
        integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_key_errors = len(conn.execute("PRAGMA foreign_key_check").fetchall())
        for table in table_names:
            try:
                counts[table] = int(conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0])
            except sqlite3.OperationalError:
                counts[table] = 0
    return {
        "engine": "SQLite",
        "path": DB_PATH,
        "filename": os.path.basename(DB_PATH),
        "size": database_file_size(DB_PATH),
        "walSize": database_file_size(f"{DB_PATH}-wal"),
        "shmSize": database_file_size(f"{DB_PATH}-shm"),
        "journalMode": journal_mode,
        "synchronous": synchronous,
        "foreignKeys": foreign_keys,
        "busyTimeoutMs": DB_BUSY_TIMEOUT_MS,
        "pageCount": page_count,
        "pageSize": page_size,
        "estimatedDataSize": page_count * page_size,
        "integrity": integrity,
        "foreignKeyErrors": foreign_key_errors,
        "counts": counts,
        "backupCount": len(backup_items),
        "lastBackup": backup_items[0] if backup_items else None,
    }


def ensure_startup_backup() -> None:
    if USE_POSTGRES:
        return
    if not os.path.exists(DB_PATH):
        return
    ensure_backup_dir()
    marker = datetime.now().strftime("%Y%m%d")
    existing = [item for item in list_database_backups() if marker in item["filename"] and "startup" in item["filename"]]
    if existing:
        return
    create_database_backup("startup")
    prune_database_backups()


def ensure_upload_dirs() -> None:
    os.makedirs(PRODUCT_UPLOAD_DIR, exist_ok=True)
    os.makedirs(STORE_UPLOAD_DIR, exist_ok=True)


def allowed_product_image(filename: str) -> bool:
    extension = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    return extension in ALLOWED_PRODUCT_IMAGE_EXTENSIONS


def image_content_matches_extension(file_storage) -> bool:
    extension = (
        file_storage.filename.rsplit(".", 1)[-1].lower()
        if "." in file_storage.filename
        else ""
    )
    file_storage.stream.seek(0)
    header = file_storage.stream.read(16)
    file_storage.stream.seek(0)
    if extension in {"jpg", "jpeg"}:
        return header.startswith(b"\xff\xd8\xff")
    if extension == "png":
        return header.startswith(b"\x89PNG\r\n\x1a\n")
    if extension == "webp":
        return (
            len(header) >= 12
            and header[:4] == b"RIFF"
            and header[8:12] == b"WEBP"
        )
    return False


def save_product_image(file_storage) -> dict:
    if not file_storage or not file_storage.filename:
        raise ValueError("Envie uma imagem.")
    if not allowed_product_image(file_storage.filename):
        raise ValueError("Formato inválido. Use JPG, PNG ou WEBP.")
    if not image_content_matches_extension(file_storage):
        raise ValueError(
            "O conteudo do arquivo nao corresponde a uma imagem valida."
        )
    file_storage.stream.seek(0, os.SEEK_END)
    size = file_storage.stream.tell()
    file_storage.stream.seek(0)
    if size > MAX_PRODUCT_IMAGE_BYTES:
        raise ValueError("Imagem maior que 5MB.")
    extension = file_storage.filename.rsplit(".", 1)[-1].lower()
    base_name = secure_filename(file_storage.filename.rsplit(".", 1)[0]) or "produto"
    file_storage.stream.seek(0)
    if USE_CLOUDINARY:
        try:
            import cloudinary
            import cloudinary.uploader
        except ImportError as exc:
            raise ValueError("Cloudinary nao instalado. Verifique requirements.txt e refaca o deploy.") from exc
        config = {"secure": True}
        if VALID_CLOUDINARY_URL:
            os.environ["CLOUDINARY_URL"] = CLOUDINARY_URL
        elif CLOUDINARY_CLOUD_NAME and CLOUDINARY_API_KEY and CLOUDINARY_API_SECRET:
            config.update({
                "cloud_name": CLOUDINARY_CLOUD_NAME,
                "api_key": CLOUDINARY_API_KEY,
                "api_secret": CLOUDINARY_API_SECRET,
            })
        cloudinary.config(**config)
        result = cloudinary.uploader.upload(
            file_storage.stream,
            folder=CLOUDINARY_FOLDER,
            public_id=f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{os.urandom(4).hex()}-{base_name}",
            resource_type="image",
            overwrite=False,
        )
        return {
            "url": result.get("secure_url") or result.get("url", ""),
            "filename": result.get("public_id", base_name),
            "size": size,
            "storage": "cloudinary",
        }
    ensure_upload_dirs()
    filename = f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{os.urandom(4).hex()}-{base_name}.{extension}"
    path = os.path.join(PRODUCT_UPLOAD_DIR, filename)
    file_storage.save(path)
    return {"url": f"/uploads/products/{filename}", "filename": filename, "size": os.path.getsize(path), "storage": "local"}


