@app.post("/api/users")
def create_user():
    _, error_response = require_admin()
    if error_response:
        return error_response
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"ok": False, "error": "Envie um JSON válido."}), 400
    user = normalize_user_payload(payload)
    error = validate_user_payload(user, creating=True)
    if error:
        return jsonify({"ok": False, "error": error}), 400
    with connect_db() as conn:
        duplicate = conn.execute(
            """
            SELECT id FROM users
            WHERE store_id = ? AND login = ? AND id <> ?
            """,
            ("matriz", user["login"], user["id"]),
        ).fetchone()
        if duplicate:
            return jsonify({"ok": False, "error": "Usuário já cadastrado."}), 409
        conn.execute(
            """
            INSERT INTO users (id, store_id, name, login, password_hash, role, active, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                user["id"],
                "matriz",
                user["name"],
                user["login"],
                generate_password_hash(user["password"]),
                user["role"],
                1 if user["active"] else 0,
                user["updatedAt"],
            ),
        )
        public = public_user(user)
        record_audit("create", "user", user["id"], {"user": public}, conn)
    sync_user_to_state(public)
    return jsonify({"ok": True, "data": public}), 201


@app.put("/api/users/<user_id>")
def update_user(user_id: str):
    current_user, error_response = require_admin()
    if error_response:
        return error_response
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"ok": False, "error": "Envie um JSON válido."}), 400
    init_db()
    with connect_db() as conn:
        row = conn.execute(
            """
            SELECT id, name, login, role, active, password_hash
            FROM users
            WHERE store_id = ? AND id = ?
            """,
            ("matriz", user_id),
        ).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Usuário não encontrado."}), 404
        user = normalize_user_payload(payload, dict(row))
        user["id"] = user_id
        error = validate_user_payload(user)
        if error:
            return jsonify({"ok": False, "error": error}), 400
        duplicate = conn.execute(
            """
            SELECT id FROM users
            WHERE store_id = ? AND login = ? AND id <> ?
            """,
            ("matriz", user["login"], user_id),
        ).fetchone()
        if duplicate:
            return jsonify({"ok": False, "error": "Usuário já cadastrado."}), 409
        if (
            row["role"] == "admin"
            and bool(row["active"])
            and (user["role"] != "admin" or not user["active"])
            and active_admin_count(conn, excluding_user_id=user_id) == 0
        ):
            return jsonify({
                "ok": False,
                "error": "A loja deve manter pelo menos um administrador ativo.",
            }), 409
        password_hash = generate_password_hash(user["password"]) if user["password"] else row["password_hash"]
        conn.execute(
            """
            UPDATE users
            SET name = ?, login = ?, password_hash = ?, role = ?, active = ?, updated_at = ?
            WHERE store_id = ? AND id = ?
            """,
            (
                user["name"],
                user["login"],
                password_hash,
                user["role"],
                1 if user["active"] else 0,
                user["updatedAt"],
                "matriz",
                user_id,
            ),
        )
        updated = conn.execute(
            """
            SELECT id, name, login, role, active, blocked_at,
                   failed_login_attempts, last_login_at
            FROM users
            WHERE store_id = ? AND id = ?
            """,
            ("matriz", user_id),
        ).fetchone()
        record_audit("update", "user", user_id, {"user": public_user(user)}, conn)
    sync_user_to_state(public_user(user))
    public = public_user(updated)
    if current_user and current_user.get("id") == user_id:
        session["user"] = public
    return jsonify({"ok": True, "data": public})


@app.delete("/api/users/<user_id>")
def delete_user_api(user_id: str):
    current_user, error_response = require_admin()
    if error_response:
        return error_response
    if current_user and current_user.get("id") == user_id:
        return jsonify({"ok": False, "error": "Não é possível excluir o usuário logado."}), 409
    init_db()
    with connect_db() as conn:
        row = conn.execute(
            "SELECT id, role, active FROM users WHERE store_id = ? AND id = ?",
            ("matriz", user_id),
        ).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Usuário não encontrado."}), 404
        if row["role"] == "admin":
            if bool(row["active"]) and active_admin_count(conn, excluding_user_id=user_id) == 0:
                return jsonify({"ok": False, "error": "Não é possível excluir o último administrador."}), 409
        if not row["active"]:
            return jsonify({"ok": True, "changed": False})
        conn.execute(
            "UPDATE users SET active = 0, updated_at = ? WHERE store_id = ? AND id = ?",
            (utc_now(), "matriz", user_id),
        )
        record_audit("deactivate", "user", user_id, {"role": row["role"]}, conn)
    sync_user_to_state({"id": user_id, "active": False})
    return jsonify({"ok": True, "changed": True})


@app.post("/api/users/<user_id>/unlock")
def unlock_user_api(user_id: str):
    _, error_response = require_admin()
    if error_response:
        return error_response
    with connect_db() as conn:
        row = conn.execute(
            "SELECT id, login, blocked_at, failed_login_attempts FROM users WHERE store_id = ? AND id = ?",
            ("matriz", user_id),
        ).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Usuario nao encontrado."}), 404
        changed = bool(row["blocked_at"] or row["failed_login_attempts"])
        if changed:
            conn.execute(
                """
                UPDATE users
                SET failed_login_attempts = 0, blocked_at = NULL, updated_at = ?
                WHERE store_id = ? AND id = ?
                """,
                (utc_now(), "matriz", user_id),
            )
            record_audit(
                "unlock",
                "user",
                user_id,
                {"previousAttempts": row["failed_login_attempts"]},
                conn,
            )
            clear_login_failures(row["login"])
    return jsonify({"ok": True, "changed": changed})


