    init_db()
    ensure_startup_backup()
    host = os.environ.get("HOST", "127.0.0.1")
    try:
        port = int(float(os.environ.get("PORT", "5005") or 5005))
    except ValueError:
        port = 5005
    app.run(host=host, port=port, debug=not IS_PRODUCTION, use_reloader=False)
